const mysql = require('mysql2/promise');

const tableNames = $vars.tables;
//const tableNames = ["data_analysis_data_source__88__88"];
const database = $vars.database;
//const database = "data_pipeline";

try {
    const connection = await mysql.createConnection({
        host: $vars.host,
        port: Number($vars.port),
        user: $vars.user,
        password: $vars.password,
        //host: "llmops-mariadb-service",
        //port: Number(3306),
        //user: "data_analysis",
        //password: "data_analysis1!",
        database: database
    });

    if (!Array.isArray(tableNames) || tableNames.length === 0) {
        throw new Error("rdb_table must be a non-empty array.");
    }

    // 결과 테이블 스키마들
    const schemaList = [];

    for (const tableName of tableNames) {
        // 컬럼 정보만 심플하게 추출
        const [columnsData] = await connection.execute(`
            SELECT 
                COLUMN_NAME,
                DATA_TYPE,
                COLUMN_KEY
            FROM INFORMATION_SCHEMA.COLUMNS
            WHERE TABLE_SCHEMA = ? AND TABLE_NAME = ?
            ORDER BY ORDINAL_POSITION
        `, [database, tableName]);

        // 컬럼별 유니크 값: 15개 이하일 때만 불러오기
        const minimalColumns = [];
        for (const col of columnsData) {
            let colInfo = {
                name: col.COLUMN_NAME,
                type: col.DATA_TYPE
            };
            if (col.COLUMN_KEY === 'PRI') colInfo.primary = true;
            else if (col.COLUMN_KEY === 'UNI') colInfo.unique = true;
            // 유니크 값 추출 (15개 이하면)
            try {
                const [res] = await connection.execute(
                    `SELECT COUNT(DISTINCT \`${col.COLUMN_NAME}\`) as cnt FROM \`${tableName}\``
                );
                if (res[0].cnt > 0 && res[0].cnt <= 15) {
                    const [values] = await connection.execute(
                        `SELECT DISTINCT \`${col.COLUMN_NAME}\` as val FROM \`${tableName}\` WHERE \`${col.COLUMN_NAME}\` IS NOT NULL LIMIT 15`
                    );
                    colInfo.unique_values = values.map(r => r.val);
                }
            } catch {}
            minimalColumns.push(colInfo);
        }

        schemaList.push({
            table_name: tableName,
            columns: minimalColumns
        });
    }

    await connection.end();

    // 리턴: 핵심 정보만
    return {"tables": schemaList};

} catch (error) {
    return {
        error: error.message,
        debug_info: {
            host: $vars.host,
            port: Number($vars.port),
            user: $vars.user,
            password: $vars.password,
            database: database,
            tables: tableNames
        }
    };
}

