const dataFormat = $DATA_FORMAT;
const chartTitle = $CHART_TITLE;
const chartUnit = $CHART_UNIT;

let sqlResult;
try {
  sqlResult = JSON.parse($SQL_RESULT);
} catch (e) {
  throw new Error("sql_result 파싱 실패: " + e.message);
}

let {
    chart_type = "bar",
    title = "",
    x_key = null,
    y_key = null,
    x_label = null,
    y_label = null,
    unit = ""
  } = dataFormat;

const keys = Object.keys(sqlResult.data[0]);
const chosenXKey = x_key || keys[0];
const chosenYKey = y_key || keys[1];

title = chartTitle;
unit = chartUnit;

const x_values = sqlResult.data.map(item => item[chosenXKey]);
const y_values = sqlResult.data.map(item => item[chosenYKey]);

return {
    chart_type,
    title,
    x_values,
    y_values,
    x_label: x_label || chosenXKey,
    y_label: y_label || chosenYKey,
    unit
  };

